import{_ as e,o,c as s,l as n,t as a,N as i}from"./chunks/framework.Bbd9fWQx.js";const f=JSON.parse('{"title":"git-ls-tree | x-cmd man (git man1) | List the contents of a tree object","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-ls-tree - List the contents of a tree object","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-ls-tree | x-cmd man (git man1) | List the contents of a tree object"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-ls-tree - List the contents of a tree object"}]]},"headers":[],"params":{"isMan":true,"man":"git-ls-tree","category":"git man1","desc":"List the contents of a tree object"},"relativePath":"git/man1/git-ls-tree.md","filePath":"git/man1/git-ls-tree.md"}'),r={name:"git/man1/git-ls-tree.md"},l={class:"visually-hidden"},h=i(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-ls-tree - List the contents of a tree object</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls-tree</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-d] [-r] [-t] [-l] [-z]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[--name-only] [--name-status] [--object-only] [--full-name] [--full-tree] [--abbrev[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]] [--format</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">format</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tree-ish</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">path</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Lists the contents of a given tree object, like what &quot;/bin/ls -a&quot; does in the current working directory. Note that:</p><blockquote><p>·</p><p>the behaviour is slightly different from that of &quot;/bin/ls&quot; in that the <em>&lt;path&gt;</em> denotes just a list of patterns to match, e.g. so specifying directory name (without <strong>-r</strong>) will behave differently, and order of the arguments does not matter.</p></blockquote><blockquote><p>·</p><p>the behaviour is similar to that of &quot;/bin/ls&quot; in that the <em>&lt;path&gt;</em> is taken as relative to the current working directory. E.g. when you are in a directory <em>sub</em> that has a directory <em>dir</em>, you can run <em>git ls-tree -r HEAD dir</em> to list the contents of the tree (that is <strong>sub/dir</strong> in <strong>HEAD</strong>). You don&#39;t want to give a tree that is not at the root level (e.g. <strong>git ls-tree -r HEAD:sub dir</strong>) in this case, as that would result in asking for <strong>sub/sub/dir</strong> in the <strong>HEAD</strong> commit. However, the current working directory can be ignored by passing --full-tree option.</p></blockquote><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>&lt;tree-ish&gt;</p><blockquote><p>Id of a tree-ish.</p></blockquote><p>-d</p><blockquote><p>Show only the named tree entry itself, not its children.</p></blockquote><p>-r</p><blockquote><p>Recurse into sub-trees.</p></blockquote><p>-t</p><blockquote><p>Show tree entries even when going to recurse them. Has no effect if <strong>-r</strong> was not passed. <strong>-d</strong> implies <strong>-t</strong>.</p></blockquote><p>-l, --long</p><blockquote><p>Show object size of blob (file) entries.</p></blockquote><p>-z</p><blockquote><p>\\0 line termination on output and do not quote filenames. See OUTPUT FORMAT below for more information.</p></blockquote><p>--name-only, --name-status</p><blockquote><p>List only filenames (instead of the &quot;long&quot; output), one per line. Cannot be combined with <strong>--object-only</strong>.</p></blockquote><p>--object-only</p><blockquote><p>List only names of the objects, one per line. Cannot be combined with <strong>--name-only</strong> or <strong>--name-status</strong>. This is equivalent to specifying <strong>--format=&#39;%(objectname)&#39;</strong>, but for both this option and that exact format the command takes a hand-optimized codepath instead of going through the generic formatting mechanism.</p></blockquote><p>--abbrev[=&lt;n&gt;]</p><blockquote><p>Instead of showing the full 40-byte hexadecimal object lines, show the shortest prefix that is at least <em>&lt;n&gt;</em> hexdigits long that uniquely refers the object. Non default number of digits can be specified with --abbrev=&lt;n&gt;.</p></blockquote><p>--full-name</p><blockquote><p>Instead of showing the path names relative to the current working directory, show the full path names.</p></blockquote><p>--full-tree</p><blockquote><p>Do not limit the listing to the current working directory. Implies --full-name.</p></blockquote><p>--format=&lt;format&gt;</p><blockquote><p>A string that interpolates <strong>%(fieldname)</strong> from the result being shown. It also interpolates <strong>%%</strong> to <strong>%</strong>, and <strong>%xx</strong> where <strong>xx</strong> are hex digits interpolates to character with hex code <strong>xx</strong>; for example <strong>%00</strong> interpolates to <strong>\\0</strong> (NUL), <strong>%09</strong> to <strong>\\t</strong> (TAB) and <strong>%0a</strong> to <strong>\\n</strong> (LF). When specified, <strong>--format</strong> cannot be combined with other format-altering options, including <strong>--long</strong>, <strong>--name-only</strong> and <strong>--object-only</strong>.</p></blockquote><p>[&lt;path&gt;...]</p><blockquote><p>When paths are given, show them (note that this isn&#39;t really raw pathnames, but rather a list of patterns to match). Otherwise implicitly uses the root level of the tree as the sole path argument.</p></blockquote><h2 id="output-format" tabindex="-1">OUTPUT FORMAT <a class="header-anchor" href="#output-format" aria-label="Permalink to &quot;OUTPUT FORMAT&quot;">​</a></h2><p>The output format of <strong>ls-tree</strong> is determined by either the <strong>--format</strong> option, or other format-altering options such as <strong>--name-only</strong> etc. (see <strong>--format</strong> above).</p><p>The use of certain <strong>--format</strong> directives is equivalent to using those options, but invoking the full formatting machinery can be slower than using an appropriate formatting option.</p><p>In cases where the <strong>--format</strong> would exactly map to an existing option <strong>ls-tree</strong> will use the appropriate faster path. Thus the default format is equivalent to:</p><blockquote><pre><code>%(objectmode) %(objecttype) %(objectname)%x09%(path)
</code></pre></blockquote><p>This output format is compatible with what <strong>--index-info --stdin</strong> of <em>git update-index</em> expects.</p><p>When the <strong>-l</strong> option is used, format changes to</p><blockquote><pre><code>%(objectmode) %(objecttype) %(objectname) %(objectsize:padded)%x09%(path)
</code></pre></blockquote><p>Object size identified by &lt;objectname&gt; is given in bytes, and right-justified with minimum width of 7 characters. Object size is given only for blobs (file) entries; for other entries <strong>-</strong> character is used in place of size.</p><p>Without the <strong>-z</strong> option, pathnames with &quot;unusual&quot; characters are quoted as explained for the configuration variable <strong>core.quotePath</strong> (see <strong>git-config</strong>(1)). Using <strong>-z</strong> the filename is output verbatim and the line is terminated by a NUL byte.</p><p>Customized format:</p><p>It is possible to print in a custom format by using the <strong>--format</strong> option, which is able to interpolate different fields using a <strong>%(fieldname)</strong> notation. For example, if you only care about the &quot;objectname&quot; and &quot;path&quot; fields, you can execute with a specific &quot;--format&quot; like</p><blockquote><pre><code>git ls-tree --format=&#39;%(objectname) %(path)&#39; &lt;tree-ish&gt;
</code></pre></blockquote><h2 id="field-names" tabindex="-1">FIELD NAMES <a class="header-anchor" href="#field-names" aria-label="Permalink to &quot;FIELD NAMES&quot;">​</a></h2><p>Various values from structured fields can be used to interpolate into the resulting output. For each outputing line, the following names can be used:</p><p>objectmode</p><blockquote><p>The mode of the object.</p></blockquote><p>objecttype</p><blockquote><p>The type of the object (<strong>commit</strong>, <strong>blob</strong> or <strong>tree</strong>).</p></blockquote><p>objectname</p><blockquote><p>The name of the object.</p></blockquote><p>objectsize[:padded]</p><blockquote><p>The size of a <strong>blob</strong> object (&quot;-&quot; if it&#39;s a <strong>commit</strong> or <strong>tree</strong>). It also supports a padded format of size with &quot;%(objectsize:padded)&quot;.</p></blockquote><p>path</p><blockquote><p>The pathname of the object.</p></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,62);function p(t,g,c,u,d,m){return o(),s("div",null,[n("h1",l,a(t.$params.man),1),h])}const k=e(r,[["render",p]]);export{f as __pageData,k as default};
